body.query:
	*[_type == 'news.article' && slug.current == $slug][0] {
		author -> {
			email,
			firstName,
			image,
			lastName,
			jobTitle,
		},
		body[] {
			...,
			_type == "blockContent" => { 
  ...,
  "text": coalesce(text[] { ..., 
  "markDefs": coalesce(markDefs[] {
    ...,
    _type == "internalLink" => { "target": link-> { 
  _type,
  "slug": slug.current,
  "category": categories[0]->slug.current
 } }
  }, [])
 }, [])
 },
			_type == "grid" => {
				items[] {
					...,
					_type == "blockContent" => { 
  ...,
  "text": coalesce(text[] { ..., 
  "markDefs": coalesce(markDefs[] {
    ...,
    _type == "internalLink" => { "target": link-> { 
  _type,
  "slug": slug.current,
  "category": categories[0]->slug.current
 } }
  }, [])
 }, [])
 }
				}
			}
		},
		categories[] -> {
			"slug": slug.current,
			title
		},
		excerpt,
		featuredImage,
		meta { metaTitle, metaDescription, openGraphImage},
		publishedAt,
		"slug": slug.current,
		title,
	}
